for(let i=1;i<crit.length;i++){const r=crit[i]||[];if(names[nz(r[CX.investor])]){critRows.push((i+1)+' '+s(r[CX.investor])+' was '+s(r[CX.status]));put('INVESTOR_CRITERIA!'+colL(CX.status)+(i+1),'HOLD');put('INVESTOR_CRITERIA!'+colL(CX.rule_notes)+(i+1),(s(r[CX.rule_notes])?s(r[CX.rule_notes])+' | ':'')+NOTE+' (was '+s(r[CX.status])+')');}}
const ph=pipe[0].map(s);const X={};ph.forEach((k,i)=>X[k]=i);let held=0,stopped=0;const heldList=[],stoppedList=[];
for(let i=1;i<pipe.length;i++){const r=pipe[i]||[];const g=k=>s(r[X[k]]);if(!(names[nz(g('investor'))]||hit(g('email')))){continue;}const rn=i+1;const sent=/^yes$/i.test(g('deal_shared'));const paused=/^yes$/i.test(g('pause'));const notes=g('notes');
  if(!sent&&!paused){put('PIPELINE!'+colL(X.pause)+rn,'Yes');put('PIPELINE!'+colL(X.next_action)+rn,'HOLD - until Equanimity thesis call 30 Sep');put('PIPELINE!'+colL(X.notes)+rn,(notes?notes+' | ':'')+NOTE);held++;heldList.push(g('startup')+' '+g('next_due'));}
