if(invRows.length<1||invRows.length>4){throw new Error('ABORT unexpected investor rows '+invRows.join(';'));}
return [{json:{dry:dry,investors_rows:invRows,criteria_rows:critRows,queued_held:held,held:heldList,followups_stopped:stopped,stopped:stoppedList,cells:data.length,data:dry?[]:data}}];
